import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchTerm.trim()) {
      navigate(`/catalog?search=${searchTerm}`);
    }
  };

  return (
    <nav className="bg-white shadow-lg border-b">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <Link to="/" className="flex items-center">
            <img src="./images/logo.png" alt="LUNA AUREA" className="h-8" />
            <span className="ml-2 text-xl font-serif font-bold">LUNA AUREA</span>
          </Link>

          {/* Navigation Links */}
          <div className="hidden md:flex space-x-8">
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600">КАТАЛОГ</Link>
            <Link to="/catalog" className="text-gray-700 hover:text-gold-600">КОЛЛЕКЦИИ</Link>
            <Link to="/about" className="text-gray-700 hover:text-gold-600">О НАС</Link>
            <Link to="/contacts" className="text-gray-700 hover:text-gold-600">КОНТАКТЫ</Link>
          </div>

          {/* Icons */}
          <div className="flex items-center space-x-4">
            {/* Search */}
            <form onSubmit={handleSearch} className="relative">
              <input
                type="text"
                placeholder="Поиск..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-3 pr-10 py-1 border rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-gold-500"
              />
              <button type="submit" className="absolute right-3 top-1/2 transform -translate-y-1/2">
                🔍
              </button>
            </form>

            {/* Profile */}
            <Link to={user ? "/profile" : "/auth"} className="p-2 hover:bg-gray-100 rounded-full">
              👤
            </Link>

            {/* Favorites */}
            <Link to="" className="p-2 hover:bg-gray-100 rounded-full">
              ❤️
            </Link>

            {/* Cart */}
            <Link to="/profile?tab=cart" className="p-2 hover:bg-gray-100 rounded-full relative">
              🛒
              {user?.cart?.length > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
                  {user.cart.length}
                </span>
              )}
            </Link>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
